function processImages() {
	for (let f of faces) {
		f.loadPixels();
		let x = 0;
		let y = 0;
		for (let i = 0; i < f.pixels.length; i += 4) {
			if (dist(x, y, f.width / 2, f.height / 2) > (f.height / 2) * 0.98) f.pixels[i + 3] = 0;
			x += 1;
			if (x >= f.width) {
				x = 0;
				y += 1;
			}
		}
		f.updatePixels();
	}
}

